def fix_content(content, issues):
    lines=content.splitlines(True)
    new_lines=[]
    for line in lines:
        has_nl=line.endswith('\n')
        core=line.rstrip('\r\n')
        core=core.rstrip(' \t')
        core=core.replace('\t','    ')
        m=re.match(r'^(\s*)([*+])(\s)', core)
        if m:
            core=m.group(1)+'-'+m.group(3)+core[len(m.group(0)):]
        m2=re.match(r'^(\s*)([-*+]|\d+\.)(\s+)', core)
        if m2:
            core=m2.group(1)+m2.group(2)+' '+core[len(m2.group(0)):]
        leading=len(core)-len(core.lstrip(' '))
        content_part=core[leading:]
        content_part=re.sub(r' {2,}', ' ', content_part)
        core=' '*leading+content_part
        if has_nl:
            core+='\n'
        new_lines.append(core)
    content2=''.join(new_lines)
    content2=re.sub(r'\n{3,}', '\n\n', content2)
    if content2 and not content2.endswith('\n'):
        content2+='\n'
    elif content2.endswith('\n\n'):
        content2=content2.rstrip('\n')+'\n'
    raw=content2.splitlines()
    new_raw=[]
    for i, line in enumerate(raw):
        is_heading=bool(re.match(r'^#{1,6} ', line.strip()))
        if is_heading:
            if new_raw and new_raw[-1].strip()!="":
                new_raw.append("")
            new_raw.append(line)
            if i+1 < len(raw) and raw[i+1].strip()!="":
                new_raw.append("")
        else:
            new_raw.append(line)
    content2='\n'.join(new_raw)
    if content and content.endswith('\n') and not content2.endswith('\n'):
        content2+='\n'
    content2=re.sub(r'\n{3,}', '\n\n', content2)
    if content2 and not content2.endswith('\n'):
        content2+='\n'
    return content2

def filter_issues(issues, opts):
    disable=[x.upper() for x in opts.get("disable",[])+opts.get("extend_disable",[])]
    enable=[x.upper() for x in opts.get("enable",[])+opts.get("extend_enable",[])]
    filtered=[]
    for iss in issues:
        code=iss["rule"].upper()
        if enable and code not in enable:
            continue
        if code in disable:
            continue
        filtered.append(iss)
    return filtered

def format_issues(issues, output_format, show_full_path=False):
    if output_format in ("text","full","concise"):
        lines=[]
        for iss in issues:
            path=iss["file"]
            if show_full_path:
                path=os.path.abspath(path)
            fix_mark=""
            if output_format=="text":
                fix_mark=" [*]" if iss.get("fixable") else ""
            elif output_format=="full":
                fix_mark=" [*]" if iss.get("fixable") else ""
            lines.append(f"{path}:{iss['line']}:{iss['column']}: [{iss['rule']}] {iss['message']}{fix_mark}")
        return "\n".join(lines)
    elif output_format=="grouped":
        from collections import defaultdict
        grouped=defaultdict(lambda: defaultdict(list))
        for iss in issues:
            grouped[iss["file"]][iss["rule"]].append(iss)
        lines=[]
        for f, rules in grouped.items():
            lines.append(f"{f}:")
            for rule, iss_list in sorted(rules.items()):
                lines.append(f"  {rule}:")
                for iss in sorted(iss_list, key=lambda x: x["line"]):
                    fixable_str=" (fixable)" if iss.get("fixable") else ""
                    lines.append(f"    {iss['line']}:{iss['column']} {iss['message']}{fixable_str}")
        return "\n".join(lines)
    elif output_format=="json":
        arr=[]
        for iss in issues:
            arr.append({"file":iss["file"],"line":iss["line"],"column":iss["column"],"rule":iss["rule"],"message":iss["message"],"severity":iss["severity"],"fixable":iss["fixable"],"fix":None})
        return json.dumps(arr, indent=2)
    elif output_format=="json-lines":
        return "\n".join(json.dumps({"file":iss["file"],"line":iss["line"],"column":iss["column"],"rule":iss["rule"],"message":iss["message"],"severity":iss["severity"],"fixable":iss["fixable"]}) for iss in issues)
    elif output_format=="github":
        return "\n".join(f"::warning file={iss['file']},line={iss['line']},col={iss['column']},endLine={iss['line']},endColumn={iss['column']+1},title={iss['rule']}::{iss['message']}" for iss in issues)
    elif output_format=="gitlab":
        arr=[{"description":iss["message"],"check_name":iss["rule"],"fingerprint":f"{iss['file']}-{iss['line']}-{iss['column']}-{iss['rule']}","severity":"minor","location":{"path":iss["file"],"lines":{"begin":iss["line"]}}} for iss in issues]
        return json.dumps(arr, indent=2)
    elif output_format=="pylint":
        return "\n".join(f"{iss['file']}:{iss['line']}:{iss['column']}: [{iss['rule'].replace('MD','CMD')}] {iss['message']}" for iss in issues)
    elif output_format=="azure":
        return "\n".join(f"##vso[task.logissue type=warning;sourcepath={iss['file']};linenumber={iss['line']};columnnumber={iss['column']};code={iss['rule']}]{iss['message']}" for iss in issues)
    elif output_format=="sarif":
        sarif={"$schema":"https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json","version":"2.1.0","runs":[{"tool":{"driver":{"name":"rumdl","version":VERSION,"informationUri":"https://github.com/rvben/rumdl","rules":[]}},"results":[]}]}
        seen=set()
        for iss in issues:
            if iss["rule"] not in seen:
                seen.add(iss["rule"])
                sarif["runs"][0]["tool"]["driver"]["rules"].append({"id":iss["rule"],"name":iss["rule"],"shortDescription":{"text":f"Markdown rule {iss['rule']}"},"fullDescription":{"text":f"Markdown linting rule {iss['rule']}"}})
            sarif["runs"][0]["results"].append({"ruleId":iss["rule"],"level":"warning","message":{"text":iss["message"]},"locations":[{"physicalLocation":{"artifactLocation":{"uri":iss["file"]},"region":{"startLine":iss["line"],"startColumn":iss["column"]}}}]})
        return json.dumps(sarif, indent=2)
    elif output_format=="junit":
        fails=len(issues)
        from collections import defaultdict
        by_file=defaultdict(list)
        for iss in issues:
            by_file[iss["file"]].append(iss)
        lines=[f'<?xml version="1.0" encoding="UTF-8"?>',f'<testsuites name="rumdl" tests="{len(by_file) if by_file else 1}" failures="{fails}" errors="0" time="0.005">']
        if not issues:
            lines.append(f'  <testsuite name="rumdl" tests="1" failures="0" errors="0" time="0.000">')
            lines.append(f'    <testcase name="Lint" classname="rumdl" time="0.000"/>')
            lines.append(f'  </testsuite>')
        else:
            for f, iss_list in by_file.items():
                lines.append(f'  <testsuite name="{f}" tests="1" failures="{len(iss_list)}" errors="0" time="0.000">')
                lines.append(f'    <testcase name="Lint {f}" classname="rumdl" time="0.000">')
                for iss in iss_list:
                    msg=iss["message"].replace("&","&amp;").replace("'","&apos;").replace('"',"&quot;").replace("<","&lt;").replace(">","&gt;")
                    lines.append(f'      <failure type="{iss["rule"]}" message="{msg}">{msg} at line {iss["line"]}, column {iss["column"]}</failure>')
                lines.append(f'    </testcase>')
                lines.append(f'  </testsuite>')
        lines.append(f'</testsuites>')
        return "\n".join(lines)
    else:
        return format_issues(issues,"text",show_full_path)

def discover_files(paths, exclude_patterns=None, include_patterns=None, respect_gitignore=True, no_exclude=False, force_exclude=False, config_exclude=None):
    if not paths:
        paths=["."]
    exclude_patterns=exclude_patterns or []
    include_patterns=include_patterns or []
    if config_exclude and not no_exclude:
        exclude_patterns.extend(config_exclude)
    files=[]
    for p in paths:
        if p=="-":
            continue
        pp=pathlib.Path(p)
        if not pp.exists():
            error_exit(f"Failed to find markdown files: File not found: {p}", exit_code=1)
        if pp.is_file():
            matched=False
            for pat in exclude_patterns:
                if fnmatch.fnmatch(pp.name, pat) or fnmatch.fnmatch(str(pp), pat) or fnmatch.fnmatch(str(pp), f"*{pat}*"):
                    matched=True
                    break
            if matched and not no_exclude:
                continue
            if include_patterns:
                inc=False
                for pat in include_patterns:
                    if fnmatch.fnmatch(pp.name, pat) or fnmatch.fnmatch(str(pp), pat):
                        inc=True
                        break
                if not inc:
                    continue
            if pp.suffix in (".md",".markdown",".mkd",".mdx",".qmd"):
                files.append(str(pp))
        elif pp.is_dir():
            for root, dirs, filenames in os.walk(pp):
                if respect_gitignore:
                    dirs[:]=[d for d in dirs if not any(fnmatch.fnmatch(d, pat) or d==pat for pat in exclude_patterns)]
                    # also skip .git etc
                    if ".git" in dirs:
                        dirs.remove(".git")
                for fname in filenames:
                    if fname.endswith((".md",".markdown",".mkd",".mdx",".qmd")):
                        fpath=os.path.join(root, fname)
                        rel=os.path.relpath(fpath, ".")
                        matched=False
                        for pat in exclude_patterns:
                            if fnmatch.fnmatch(fname, pat) or fnmatch.fnmatch(fpath, pat) or fnmatch.fnmatch(rel, pat):
                                matched=True
                                break
                            if "**" in pat and pat.replace("**/","").replace("**","") in fpath:
                                matched=True
                                break
                        if matched and not no_exclude:
                            continue
                        if include_patterns:
                            inc=False
                            for pat in include_patterns:
                                if fnmatch.fnmatch(fname, pat) or fnmatch.fnmatch(fpath, pat) or fnmatch.fnmatch(rel, pat):
                                    inc=True
                                    break
                            if not inc:
                                continue
                        if respect_gitignore:
                            skip=False
                            cur=pathlib.Path(fpath).parent
                            pp_res=pathlib.Path(pp).resolve()
                            while True:
                                gi=cur / ".gitignore"
                                if gi.exists():
                                    try:
                                        pats=[p.strip() for p in gi.read_text().splitlines() if p.strip() and not p.strip().startswith("#")]
                                        for pat in pats:
                                            if fnmatch.fnmatch(fname, pat) or fnmatch.fnmatch(fpath, pat):
                                                skip=True
                                                break
                                    except:
                                        pass
                                if cur==pp_res or cur==cur.parent:
                                    break
                                cur=cur.parent
                                if len(str(cur)) < len(str(pp_res)):
                                    break
                            if skip:
                                continue
                        files.append(fpath)
    return sorted(set(files))

