def get_config_file_path(start_dir=None):
    if start_dir is None:
        start_dir=os.getcwd()
    cur=pathlib.Path(start_dir).resolve()
    for p in [cur]+list(cur.parents):
        for name in [".rumdl.toml","rumdl.toml"]:
            cand=p/name
            if cand.exists():
                return str(cand)
        pyproject=p/"pyproject.toml"
        if pyproject.exists():
            try:
                txt=pyproject.read_text()
                if "rumdl" in txt:
                    return str(pyproject)
            except:
                pass
    return None

def load_config(config_path=None, no_config=False):
    if no_config:
        return json.loads(json.dumps(DEFAULT_CONFIG)), None, True
    if config_path:
        pp=pathlib.Path(config_path)
        if not pp.exists():
            error_exit(f"Failed to read config file at {config_path}: No such file or directory (os error 2)", exit_code=2)
        try:
            txt=pp.read_text()
            data={}
            # simple toml parse for our needs
            import re as re2
            current=None
            for line in txt.splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("[") and line.endswith("]"):
                    current=line[1:-1]
                    if current not in data:
                        data[current]={}
                    continue
                if "=" in line and current:
                    k,v=line.split("=",1)
                    k=k.strip(); v=v.strip()
                    # strip comment
                    v=v.split("#")[0].strip()
                    # parse value
                    try:
                        if v.startswith("["):
                            # try json
                            v=json.loads(v.replace("'",'"'))
                        elif v.startswith('"') and v.endswith('"'):
                            v=v[1:-1]
                        elif v.lower()=="true":
                            v=True
                        elif v.lower()=="false":
                            v=False
                        elif v.isdigit():
                            v=int(v)
                    except:
                        pass
                    data[current][k]=v
            cfg=json.loads(json.dumps(DEFAULT_CONFIG))
            if "global" in data:
                for k in ["disable","enable","exclude","include"]:
                    if k in data["global"]:
                        cfg["global"][k]=data["global"][k]
            if "tool" in data and "rumdl" in data["tool"]:
                g=data["tool"]["rumdl"]
                for k in ["disable","enable","exclude","include"]:
                    if k in g:
                        cfg["global"][k]=g[k]
            for k,v in data.items():
                if k.startswith("MD"):
                    cfg[k]=v
            return cfg, str(pp), False
        except SystemExit:
            raise
        except Exception as e:
            error_exit(f"Failed to read config file at {config_path}: {e}", exit_code=2)
    else:
        found=get_config_file_path()
        if found:
            return load_config(found, False)
        else:
            return json.loads(json.dumps(DEFAULT_CONFIG)), None, True

