                    print(f"\nUsage: executable config get [OPTIONS] <KEY>", file=sys.stderr)
                    print(f"\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
        if key is None:
            print(f"error: the following required arguments were not provided:\n  <KEY>", file=sys.stderr)
            print(f"\nUsage: executable config get <KEY>", file=sys.stderr)
            print(f"\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        if "." not in key:
            print(f"Key must be in the form global.key or MDxxx.key", file=sys.stderr)
            sys.exit(2)
        prefix,suffix=key.split(".",1)
        if prefix=="global":
            valid=["enable","disable","exclude","include","respect_gitignore","respect-gitignore","line-length","line_length","flavor","output-format","output_format","cache","cache_dir","cache-dir","force-exclude","force_exclude"]
            norm=suffix.replace("-","_")
            if norm not in [k.replace("-","_") for k in valid]:
                print(f"Unknown global key: {suffix}", file=sys.stderr)
                sys.exit(2)
            cfg,cfg_path2,is_def=load_config(g_config, g_no_config)
            src="from default" if is_def else "from project config"
            # map
            key_map={"enable":"enable","disable":"disable","exclude":"exclude","include":"include","respect_gitignore":"respect_gitignore","respect-gitignore":"respect_gitignore","line_length":"line-length","line-length":"line-length","flavor":"flavor","cache":"cache","cache_dir":"cache-dir","cache-dir":"cache-dir"}
            cfg_key=key_map.get(suffix, suffix)
            val=None
            if cfg_key in cfg["global"]:
                val=cfg["global"][cfg_key]
            elif cfg_key.replace("-","_") in cfg["global"]:
                val=cfg["global"][cfg_key.replace("-","_")]
            elif cfg_key.replace("_","-") in cfg["global"]:
                val=cfg["global"][cfg_key.replace("_","-")]
            else:
                val=[]
            if isinstance(val,list):
                val_str=json.dumps(val)
            elif isinstance(val,bool):
                val_str=str(val).lower()
            elif isinstance(val,str):
                val_str=f'"{val}"'
            else:
                val_str=json.dumps(val)
            print(f"{key} = {val_str} [{src}]")
            sys.exit(0)
        elif prefix.startswith("MD"):
            if not re.match(r'MD\d{3}', prefix):
                print(f"Unknown config key: {key}", file=sys.stderr)
                sys.exit(2)
            if not any(r["code"]==prefix for r in RULES):
                print(f"Unknown config key: {key}", file=sys.stderr)
                sys.exit(2)
            valid_md=["line-length","line_length","code-blocks","code_blocks","tables","headings","style","indent","front-matter-title","front_matter_title","br-spaces","br_spaces","strict","spaces-per-tab","spaces_per_tab","maximum","allow-different-nesting","allow_different_nesting","punctuation","ol-multi","ol_multi","ol-single","ol_single","ul-multi","ul_multi","ul-single","ul_single","list-items","list_items","allow-lazy-continuation","allow_lazy_continuation","allowed-elements","allowed_elements","disallowed-elements","disallowed_elements","br-style","br_style","fix","heading-level","heading_level","heading-style","heading_style","names","show-output","show_output","level","front-matter-title"]
            if suffix not in valid_md and suffix.replace("_","-") not in valid_md and suffix.replace("-","_") not in valid_md:
                print(f"Unknown config key: {key}", file=sys.stderr)
                sys.exit(2)
            cfg,cfg_path2,is_def=load_config(g_config, g_no_config)
            md_cfg=cfg.get(prefix, MD_DEFAULTS.get(prefix,{}))
            val=None
            src="from default"
            if suffix in md_cfg:
                val=md_cfg[suffix]
                if not is_def and prefix in cfg and suffix in cfg[prefix]:
                    src="from project config"
            elif suffix.replace("-","_") in md_cfg:
                val=md_cfg[suffix.replace("-","_")]
                if not is_def and prefix in cfg and suffix.replace("-","_") in cfg[prefix]:
                    src="from project config"
            elif suffix.replace("_","-") in md_cfg:
                val=md_cfg[suffix.replace("_","-")]
                if not is_def and prefix in cfg and suffix.replace("_","-") in cfg[prefix]:
                    src="from project config"
            else:
                defaults=MD_DEFAULTS.get(prefix,{})
                if suffix in defaults:
                    val=defaults[suffix]
                elif suffix.replace("-","_") in defaults:
                    val=defaults[suffix.replace("-","_")]
                elif suffix.replace("_","-") in defaults:
                    val=defaults[suffix.replace("_","-")]
            if isinstance(val,list):
                val_str=json.dumps(val)
            elif isinstance(val,bool):
                val_str=str(val).lower()
            elif isinstance(val,str):
                val_str=f'"{val}"'
            elif isinstance(val,int):
                val_str=str(val)
            else:
                val_str=json.dumps(val) if val is not None else "null"
            print(f"{key} = {val_str} [{src}]")
            sys.exit(0)
        else:
            print(f"Unknown config key: {key}", file=sys.stderr)
            sys.exit(2)
    elif subcommand=="file":
        for a in sub_args:
            if a in ("-h","--help"):
                print(load_help("config"))
                sys.exit(0)
            elif a.startswith("-"):
