    else:
        out_fmt=output or "text"
        cfg,cfg_path,is_def=load_config(config_path, no_config)
        if out_fmt=="json":
            print(json.dumps(cfg, indent=2))
            sys.exit(0)
        elif out_fmt=="toml":
            print("[global]")
            for k,v in cfg["global"].items():
                print(f"{k} = {json.dumps(v)}")
            for k,v in cfg.items():
                if k not in ("global","per-file-ignores","per-file-flavor","code-block-tools"):
                    print(f"\n[{k}]")
                    for kk,vv in v.items():
                        print(f"{kk} = {json.dumps(vv)}")
            sys.exit(0)
        else:
            if is_def and no_defaults:
                print("All configurations are using default values.")
                sys.exit(0)
            # print text config with [from ...]
            def fmt_val(v):
                if isinstance(v,str):
                    return f'"{v}"'
                elif isinstance(v,bool):
                    return "true" if v else "false"
                elif isinstance(v,list):
                    if not v:
                        return "[]"
                    inner=", ".join(f'"{x}"' if isinstance(x,str) else str(x) for x in v)
                    return f"[{inner}]"
                else:
                    return json.dumps(v)
            print("[global]")
            for k in ["enable","disable","exclude","include","respect_gitignore","flavor"]:
                # get value
                if k=="respect_gitignore":
                    val=cfg["global"].get("respect_gitignore", True)
                    src="from default" if is_def else "from project config" if cfg["global"].get("respect_gitignore") != DEFAULT_CONFIG["global"]["respect_gitignore"] else "from default"
                    print(f"{k} = {str(val).lower()} [{src}]")
                elif k=="flavor":
                    val=cfg["global"].get("flavor","standard")
                    src="from default" if is_def else "from project config" if val != DEFAULT_CONFIG["global"]["flavor"] else "from default"
                    # capitalize
                    val_disp=val.capitalize() if isinstance(val,str) else val
                    print(f"{k} = {val_disp} [{src}]")
                else:
                    val=cfg["global"].get(k, [])
                    src="from default" if is_def else "from project config" if val != DEFAULT_CONFIG["global"].get(k) else "from default"
                    line=f"{k} = {fmt_val(val)}"
                    pad=120 - len(line)
                    if pad<1:
                        pad=1
                    print(f"{line}{' '*pad}[{src}]")
            # MD sections - show some
            for md in sorted([k for k in list(MD_DEFAULTS.keys())+list(cfg.keys()) if k.startswith("MD")]):
                # dedupe
                if md not in MD_DEFAULTS and md not in cfg:
                    continue
                print(f"\n[{md}]")
                defaults=MD_DEFAULTS.get(md,{})
                cfg_vals=cfg.get(md, defaults)
                if not isinstance(cfg_vals, dict):
                    continue
                keys=set(defaults.keys())|set(cfg_vals.keys())
                for kk in sorted(keys):
                    val=cfg_vals.get(kk, defaults.get(kk))
                    src="from default"
                    if not is_def and md in cfg and kk in cfg[md] and cfg[md][kk]!=defaults.get(kk):
                        src="from project config"
                    line=f"{kk} = {fmt_val(val)}"
                    pad=120 - len(line)
                    if pad<1:
                        pad=1
                    print(f"{line}{' '*pad}[{src}]")
            sys.exit(0)

