        print(f"error: the following required arguments were not provided:\n  <FILE>", file=sys.stderr)
        print(f"\nUsage: executable import <FILE>", file=sys.stderr)
        print(f"\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)
    p=pathlib.Path(file_arg)
    if not p.exists():
        print(f"Import error: Failed to read config file {file_arg}: No such file or directory (os error 2)", file=sys.stderr)
        sys.exit(1)
    try:
        txt=p.read_text()
        data=None
        if p.suffix==".json":
            data=json.loads(txt)
        elif p.suffix in (".yaml",".yml"):
            try:
                import yaml
                data=yaml.safe_load(txt)
            except:
                data={}
                current=None
                for line in txt.splitlines():
                    line=line.strip()
                    if not line or line.startswith("#"):
                        continue
                    if line.endswith(":"):
                        current=line[:-1]
                        data[current]={}
                    elif ":" in line and current:
                        k,v=line.split(":",1)
                        k=k.strip(); v=v.strip()
                        if v.lower()=="false":
                            v=False
                        elif v.lower()=="true":
                            v=True
                        elif v.isdigit():
                            v=int(v)
                        data[current][k]=v
                    elif ":" in line:
                        k,v=line.split(":",1)
                        k=k.strip(); v=v.strip()
                        if v.lower()=="false":
                            data[k]=False
                        elif v.lower()=="true":
                            data[k]=True
                        else:
                            data[k]=v
        else:
            try:
                data=json.loads(txt)
            except:
                data={}
        disable=[]
        md_configs={}
        for k,v in data.items():
            if k=="default":
                continue
            if isinstance(v,bool) and v==False:
                if re.match(r'MD\d{3}',k):
                    disable.append(k)
            elif isinstance(v,dict):
                if re.match(r'MD\d{3}',k):
                    new_dict={}
                    for kk,vv in v.items():
                        new_k=kk.replace("_","-")
                        new_dict[new_k]=vv
                    md_configs[k]=new_dict
        if fmt=="toml":
            out_lines=[]
            if disable:
                out_lines.append("[global]")
                out_lines.append(f"disable = {json.dumps(disable)}")
                out_lines.append("")
            for md,cfg in md_configs.items():
                out_lines.append(f"[{md}]")
                for kk,vv in cfg.items():
                    if isinstance(vv,str):
                        out_lines.append(f'{kk} = "{vv}"')
                    elif isinstance(vv,bool):
                        out_lines.append(f'{kk} = {str(vv).lower()}')
                    else:
                        out_lines.append(f'{kk} = {vv}')
                out_lines.append("")
            out_text="\n".join(out_lines).strip()+"\n" if out_lines else ""
            if dry_run:
                print(out_text, end='')
            else:
                pathlib.Path(output).write_text(out_text)
                print(f"Converted {file_arg} to {output}")
        else:
            out_data={}
            if disable:
                out_data["global"]={"disable":disable}
            for md,cfg in md_configs.items():
                out_data[md]=cfg
            out_text=json.dumps(out_data, indent=2)
            if dry_run:
                print(out_text)
            else:
                pathlib.Path(output).write_text(out_text)
                print(f"Converted {file_arg} to {output}")
        sys.exit(0)
    except SystemExit:
        raise
    except Exception as e:
        print(f"Import error: Failed to read config file {file_arg}: {e}", file=sys.stderr)
        sys.exit(1)

